from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject


class GNSS(SchemaObject):
    status = SchemaField(name="status")
    constellations_supported = SchemaField(name="constellationsSupported")
    constellations_enabled = SchemaField(name="constellationsEnabled")

    def __init__(self, status, constellations_supported, constellations_enabled):
        self.status = status
        self.constellations_supported = constellations_supported
        self.constellations_enabled = constellations_enabled
        super(GNSS, self).__init__()


class GNSS22A(SchemaObject):
    gnss = SchemaField(name="gnss", klass=GNSS)
    coordinates = SchemaField(name="coordinates")

    def __init__(self, gnss, coordinates):
        self.gnss = gnss
        self.coordinates = coordinates
        super(GNSS22A, self).__init__()
